from __future__ import annotations

import json
import sys
import os
from pathlib import Path

import pandas as pd
from docx import Document
from docx.enum.table import WD_CELL_VERTICAL_ALIGNMENT, WD_TABLE_ALIGNMENT
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.oxml import OxmlElement
from docx.oxml.ns import qn
from docx.shared import Cm, Pt


COMBINED = "--combined" in sys.argv
PROJECT = Path(__file__).resolve().parents[1]
OUT = Path(os.environ.get(
    "GALLICA_ANALYSIS_OUT",
    PROJECT / "outputs" / ("combined" if COMBINED else "events_only"),
))


def fmt(value, digits=2):
    if isinstance(value, float):
        return f"{value:.{digits}f}".replace(".", ",")
    return str(value)


def nfmt(value):
    return f"{int(value):,}".replace(",", " ")


def shade(cell, fill):
    tc_pr = cell._tc.get_or_add_tcPr()
    shd = tc_pr.find(qn("w:shd"))
    if shd is None:
        shd = OxmlElement("w:shd")
        tc_pr.append(shd)
    shd.set(qn("w:fill"), fill)


def add_table(doc, headers, rows, widths=None):
    table = doc.add_table(rows=1, cols=len(headers))
    table.style = "Table Grid"
    table.alignment = WD_TABLE_ALIGNMENT.CENTER
    table.autofit = False
    for i, value in enumerate(headers):
        cell = table.rows[0].cells[i]
        cell.text = str(value)
        shade(cell, "D9E5F3")
        for run in cell.paragraphs[0].runs:
            run.bold = True
    for row in rows:
        cells = table.add_row().cells
        for i, value in enumerate(row):
            cells[i].text = fmt(value)
            cells[i].vertical_alignment = WD_CELL_VERTICAL_ALIGNMENT.CENTER
    if widths:
        for row in table.rows:
            for cell, width in zip(row.cells, widths):
                cell.width = Cm(width)
    doc.add_paragraph()
    return table


def add_heading(doc, text, level=1):
    p = doc.add_paragraph()
    p.style = f"Heading {level}"
    r = p.add_run(text)
    r.bold = True
    return p


def add_body(doc, text):
    p = doc.add_paragraph(text)
    p.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY
    p.paragraph_format.first_line_indent = Cm(1)
    return p


def main():
    manifest = json.loads((OUT / "00_Манифест_исследования.json").read_text(encoding="utf-8"))
    mutual = pd.read_csv(OUT / "06_Взаимная_встречаемость_события_и_акторы_окно100.csv")
    themes = pd.read_csv(OUT / "07_Встречаемость_события_и_темы_окно100.csv")
    sensitivity = pd.read_csv(OUT / "08_Проверка_окон_50_100_150_200.csv")
    papers = pd.read_csv(OUT / "04_Состав_корпуса_по_газетам.csv")

    event_order = list(manifest["event_page_frequencies"])
    doc = Document()
    sec = doc.sections[0]
    sec.top_margin = sec.bottom_margin = Cm(2)
    sec.left_margin = sec.right_margin = Cm(2)
    normal = doc.styles["Normal"]
    normal.font.name = "Times New Roman"; normal.font.size = Pt(14)
    normal.paragraph_format.line_spacing = 1.5
    for style_name in ("Heading 1", "Heading 2"):
        style = doc.styles[style_name]
        style.font.name = "Times New Roman"; style.font.bold = True
        style.font.size = Pt(14)

    title = doc.add_paragraph()
    title.alignment = WD_ALIGN_PARAGRAPH.CENTER
    run = title.add_run("От кампаний 1812–1813 гг. к конгрессной системе: контент-анализ французских газет Gallica")
    run.bold = True; run.font.name = "Times New Roman"; run.font.size = Pt(14)

    add_heading(doc, "Аннотация")
    add_body(doc, "Исследование посвящено тому, как французские газеты представляли ключевые события внешней политики Александра I от Бородинского сражения до Веронского конгресса. На материале газетного корпуса Gallica формализованы событийные, акторные и смысловые категории. Для 100-словных фрагментов рассчитаны направленные доли совместной встречаемости; устойчивость связи событий с Александром I проверена на окнах 50, 100, 150 и 200 слов. Результаты выявляют переход от языка военного конфликта к языку порядка и многосторонней дипломатии, избирательную персонализацию событий фигурой Александра I и изменение воспринимаемого центра конгрессной политики от многостороннего Ахена через австрийское преобладание в Троппау и Лайбахе к французской проблематике Вероны.")

    add_heading(doc, "Введение")
    add_body(doc, "Французская газетная печать 1812–1822 гг. фиксировала не только последовательность военных и дипломатических событий, но и изменение языка, посредством которого объяснялся новый европейский порядок. Исследование охватывает Бородинское сражение, оставление и пожар Москвы, сражения при Лютцене и Баутцене и Лейпцигскую битву — основные этапы перехода от вторжения Наполеона в Россию к разгрому его армии и победе Шестой коалиции. Первый Парижский мир возвратил Францию к границам 1792 г., Венский конгресс перестроил территориальный и политический порядок Европы, а Второй Парижский мир закрепил более суровые условия после Ста дней. Акт Священного союза придал послевоенному сотрудничеству христианско-нравственное обоснование; Аахенский конгресс завершил оккупацию Франции и включил ее в согласование великих держав, Троппау и Лайбах выработали и применили принципы противодействия революциям, а Верона связала конгрессную систему с вопросом французского вмешательства в Испании. Победа или поражение, союз, мир, легитимность, конституция и религиозная мораль образовывали конкурирующие способы интерпретации политики России и Александра I. Последовательное количественное сопоставление этих полей позволяет выяснить, какие события персонализировались фигурой российского императора, какие представлялись результатом действий держав и как менялся смысл конгрессной системы [2–4].")
    add_body(doc, "Цель исследования — выявить структуру совместной встречаемости исторических событий, политических акторов и смысловых рамок во французских газетах. Вслед за применением формализованного контент-анализа И.В. Гребенченко единицей счета служит контекстный фрагмент, а категория определяется по заранее заданному набору лексических индикаторов [1].")

    add_heading(doc, "Корпус источников")
    if COMBINED:
        add_body(doc, f"Два исходных корпуса вместе содержали {nfmt(manifest['download_rows_before_cross_corpus_deduplication'])} записей о скачанных страницах. По ключу «ARK выпуска + физический номер страницы» удалено {nfmt(manifest['duplicate_download_rows_removed'])} межкорпусных дублей. После дедупликации осталось {nfmt(manifest['download_rows_in_database'])} уникальных страниц из {manifest['source_titles_total']} названий. Затем были исключены журналы, ревю, справочные и разовые публикации. В анализ вошло {nfmt(manifest['newspaper_pages_analyzed'])} страниц из {manifest['newspaper_titles']} газет, относящихся к {nfmt(manifest['issues'])} выпускам. Объем текста составил {nfmt(manifest['words'])} слов; при основном окне получено {nfmt(manifest['fragments_100'])} контекстных фрагментов.")
    else:
        add_body(doc, f"Исходная база загрузок содержала {nfmt(manifest['download_rows_in_database'])} страниц из {manifest['source_titles_total']} названий. После отделения газет от журналов, ревю, справочных и разовых публикаций в анализ включено {nfmt(manifest['newspaper_pages_analyzed'])} страниц из {manifest['newspaper_titles']} газет, относящихся к {nfmt(manifest['issues'])} выпускам. Объем распознанного текста составил {nfmt(manifest['words'])} слов; при основном окне получено {nfmt(manifest['fragments_100'])} контекстных фрагментов. Из анализа исключено {nfmt(manifest['excluded_pages_non_newspapers'])} страниц {manifest['excluded_titles']} негазетных названий. Все числа приведены по локальному снимку корпуса на момент расчета.")
    add_body(doc, f"В состоянии загрузчика сохраняются {manifest['ocr_request_errors_in_state_db']} неудачных OCR-запросов. Они не входят в локальный корпус и образуют возможный источник неполноты. Поэтому полученные проценты характеризуют доступный газетный корпус, а не абсолютно всю французскую прессу периода.")

    top_rows = []
    for _, r in papers.head(15).iterrows():
        top_rows.append([r["газета"], int(r["страниц"]), int(r["выпусков"]), int(r["слов"])])
    add_table(doc, ["Газета", "Страниц", "Выпусков", "Слов"], top_rows, [9.5, 2.2, 2.2, 2.8])
    doc.add_picture(str(OUT / "14_Состав_корпуса.png"), width=Cm(16))
    doc.paragraphs[-1].alignment = WD_ALIGN_PARAGRAPH.CENTER

    add_heading(doc, "Методика и кодировочная схема")
    add_body(doc, "Текст приводился к нижнему регистру, диакритика унифицировалась, а последовательности пробелов сокращались. Основной анализ выполнен для скользящих фрагментов длиной 100 слов с перекрытием 20 слов. Совместная встречаемость A → B означает долю фрагментов с категорией A, в которых присутствовала категория B. Обратная доля B → A имеет другой знаменатель и потому не обязана совпадать. Для контроля дистанционного эффекта те же расчеты повторены на окнах 50, 150 и 200 слов с перекрытием 20%.")
    add_body(doc, "Событийный код присваивался только в исторически допустимые годы. Для оставления Москвы требовалось одновременное присутствие Moscou и индикатора оставления, эвакуации, пожара либо отступления. Такое правило уменьшает число ложных совпадений. Для остальных событий использовались устойчивые топонимические или институциональные обозначения.")
    categories = [
        ["События 1812–1813 гг.", "Borodino/Borodina, Moskowa/Moscowa; Moscou + abandon/évacuer/quitter/incendie/retraite; Lützen; Bautzen/Bauzen; Leipzig/Leipsic/Leipsick"],
        ["Мирное урегулирование", "paix/traité de Paris; congrès de Vienne; Sainte-Alliance"],
        ["Конгрессы", "Aix-la-Chapelle; Troppau; Laibach/Laybach; Vérone"],
        ["Акторы", "Alexandre/empereur de Russie; Napoléon/Bonaparte; Russie/russe; France/français; Prusse/prussien; Autriche/autrichien/Metternich; Angleterre/anglais/Grande-Bretagne"],
        ["Победа и слава", "victoire, triomphe, gloire, glorieux, vainqueur"],
        ["Поражение и отступление", "défaite, retraite, fuite, désastre, perte"],
        ["Война и насилие", "guerre, bataille, combat, armée, troupes, sang, mort"],
        ["Мир и примирение", "paix, pacification, tranquillité, repos, réconciliation, concorde"],
        ["Союз и дипломатия", "alliance, traité, congrès, conférence, négociation, ambassade, plénipotentiaire"],
        ["Порядок и легитимность", "ordre, légitimité, trône, souverain, restauration, stabilité"],
        ["Свобода и конституция", "liberté, constitution, droits, indépendance, représentation"],
        ["Христианская мораль", "chrétien, religion, providence, évangile, divin, Dieu, fraternité, humanité"],
        ["Интервенция", "intervention, intervenir, invasion, occupation, expédition"],
    ]
    add_table(doc, ["Категория", "Французские индикаторы"], categories, [5.0, 11.7])

    add_heading(doc, "Результаты")
    add_heading(doc, "1. Частота событий", 2)
    event_rows = []
    for event in event_order:
        n_pages = manifest["event_page_frequencies"][event]
        n_windows = int(mutual.loc[mutual["событие"] == event, "окна_события"].iloc[0])
        status = "малая выборка" if n_windows < 30 else "пригодно для сопоставления"
        event_rows.append([event, n_pages, n_windows, status])
    add_table(doc, ["Событие", "Страниц", "100-словных окон", "Статус"], event_rows, [7.0, 2.0, 3.0, 4.7])
    if COMBINED:
        add_body(doc, "Самыми объемными событийными подкорпусами стали Венский, Аахенский, Лайбахский и Веронский конгрессы. Объединение с первым корпусом увеличило выборку по Акту Священного союза до 208 контекстных окон, поэтому эту категорию теперь можно сопоставлять с практикой конгрессной системы.")
    else:
        add_body(doc, "Самыми объемными событийными подкорпусами стали Венский, Аахенский, Лайбахский и Веронский конгрессы. По Акту Священного союза обнаружено менее 30 контекстных окон, поэтому проценты по нему не используются как основание самостоятельных исторических выводов.")
    doc.add_picture(str(OUT / "10_Частоты_событий.png"), width=Cm(16)); doc.paragraphs[-1].alignment = WD_ALIGN_PARAGRAPH.CENTER

    add_heading(doc, "2. Персонализация событий Александром I", 2)
    alex = mutual[mutual["актор"] == "Александр I"].set_index("событие")
    alex_rows = []
    for event in event_order:
        r = alex.loc[event]
        alex_rows.append([event, int(r["окна_события"]), int(r["совместных_окон"]), f"{fmt(float(r['событие_к_актору_pct']))}%", f"{fmt(float(r['актор_к_событию_pct']))}%"])
    add_table(doc, ["Событие", "Окон события", "Совместных", "Событие → Александр", "Александр → событие"], alex_rows, [6.4, 2.0, 2.0, 3.2, 3.2])
    if COMBINED:
        add_body(doc, "Ранние события не образуют единого персонализированного нарратива. Александр I почти отсутствует в непосредственных окнах Бородина, оставления Москвы и Лейпцига, но заметно присутствует в описаниях Лютцена (14,89%). Следовательно, газетная видимость государя определялась не масштабом события как такового, а тем, насколько сообщение строилось вокруг личного присутствия монарха и дипломатической инициативы.")
        add_body(doc, "В конгрессной системе максимальная доля связи с Александром наблюдается в Троппау — 27,27%. В Лайбахе она падает до 15,61%, а в Вероне — до 11,00%. Обратный показатель показывает, что 34,79% всех 100-словных фрагментов с Александром в корпусе 1820 г. одновременно относились к Троппау. Троппау остается главным узлом персонализации конгрессной политики российским императором, хотя расширенный корпус показывает более заметное присутствие Александра в Ахене и Лайбахе, чем событийный корпус отдельно. Это различие имеет содержательное основание. В Троппау Великобритания формально отказалась участвовать и направила лорда Стюарта только как наблюдателя, а французские послы играли пассивную роль; поэтому конгресс фактически стал совещанием России, Австрии и Пруссии [3, с. 18]. Александр I и И.А. Каподистрия возражали против восстановления неограниченного абсолютизма в Неаполе и, отвергая революционный способ изменения строя, допускали монархическую конституцию [4, с. 194–195]. Французская пресса одновременно делала эту позицию видимой и спорной: консервативные издания представляли Александра защитником мира и согласования допустимой конституции с безопасностью соседей, тогда как либеральные газеты связывали его имя с формирующимся правом держав вмешиваться во внутренние дела. Поэтому высокая совместная встречаемость отражает не однозначную поддержку императора, а персонализацию конфликта между умеренно-конституционным проектом и охранительной практикой союза.")
        add_body(doc, "В Лайбахе инициатива заметнее сместилась к Австрии: приглашение неаполитанского короля и перенос переговоров предложил Меттерних, после чего конгресс санкционировал прекращение революции мирными средствами или силой, а практическое исполнение решения было возложено на австрийскую армию [4, с. 195; 3, с. 18]. Это помогает объяснить одновременное снижение персональной доли Александра и сохранение высокой видимости России: российское участие не исчезло, но газетный сюжет о непосредственном действии все больше строился вокруг австрийской дипломатии и интервенции.")
    else:
        add_body(doc, "Ранние события не образуют единого персонализированного нарратива. Александр I почти отсутствует в непосредственных окнах Бородина, оставления Москвы и Лейпцига, но заметно присутствует в описаниях Лютцена (14,87%). Следовательно, газетная видимость государя определялась не масштабом события как такового, а тем, насколько сообщение строилось вокруг личного присутствия монарха и дипломатической инициативы.")
        add_body(doc, "В конгрессной системе максимальная доля связи с Александром наблюдается в Троппау — 19,29%. В Лайбахе она падает до 5,13%, а в Вероне возрастает до 10,50%. Обратный показатель показывает, что 58,56% всех 100-словных фрагментов с Александром в корпусе 1820 г. одновременно относились к Троппау. Это делает Троппау главным узлом персонализации конгрессной политики российским императором в данном корпусе.")
    doc.add_picture(str(OUT / "13_Чувствительность_к_размеру_окна.png"), width=Cm(16)); doc.paragraphs[-1].alignment = WD_ALIGN_PARAGRAPH.CENTER

    add_heading(doc, "3. Изменение акторного центра конгрессной системы", 2)
    congresses = ["Аахенский конгресс", "Троппауский конгресс", "Лайбахский конгресс", "Веронский конгресс"]
    actor_labels = ["Александр I", "Россия", "Австрия / Меттерних", "Пруссия", "Франция", "Великобритания"]
    actor_rows = []
    for event in congresses:
        vals = mutual[mutual["событие"] == event].set_index("актор")
        actor_rows.append([event] + [f"{fmt(float(vals.loc[a, 'событие_к_актору_pct']))}%" for a in actor_labels])
    add_table(doc, ["Конгресс"] + actor_labels, actor_rows, [3.7, 2.0, 1.8, 2.5, 1.7, 1.7, 2.1])
    if COMBINED:
        add_body(doc, "Ахен представлен как относительно многосторонний узел: Пруссия (29,02%), Александр I (24,65%), Россия (24,07%), Франция (22,55%) и Австрия/Меттерних (20,22%) имеют сопоставимую видимость. В Троппау и Лайбахе первое место занимает Австрия/Меттерних — соответственно 33,74 и 30,67%. При переходе от Троппау к Лайбаху персональная доля Александра уменьшается с 27,27 до 15,61%, тогда как доля России остается заметной и даже несколько возрастает — с 19,80 до 21,38%. Это различие указывает не на исчезновение России, а на частичную деперсонализацию ее присутствия и усиление институционально-австрийского образа конгрессной политики.")
        add_body(doc, "В Вероне ведущим актором становится Франция (27,11%), опережая Австрию/Меттерних (19,00%) и Россию (18,00%). Такая перестройка соответствует превращению испанской интервенции во французский внешнеполитический вопрос: газетный центр повествования смещается от инициаторов охранительной доктрины к державе, которой предстояло осуществить ее практически.")
